--## MONITORS ###

--###############

-- See https://wiki.hypr.land/Configuring/Monitors/

-- Layar laptop: selalu tetap seperti ini

-- Laptop

-- Laptop

hl.monitor({
    output   = "LVDS-1",
    mode     = "1366x768@60",
    position = "0x0",
    scale    = 1,
})

-- Rumah: TV Toshiba (VGA) → extend, resolusi penuh, di kanan laptop

hl.monitor({
    output   = "desc:Toshiba America Info Systems Inc TOSHIBA-TV 0x01010101",
    mode     = "preferred",
    position = "auto",
    scale    = 1,
})

-- Lewat mini DP (smart TV / proyektor saat presentasi) → mirror 1920x1080@60

hl.monitor({
    output   = "DP-1",
    mode     = "1920x1080@60",
    position = "auto",
    scale    = 1,
    mirror = "LVDS-1",
})

hl.monitor({
    output   = "DP-2",
    mode     = "1920x1080@60",
    position = "auto",
    scale    = 1,
    mirror = "LVDS-1",
})

-- Layar lain yang tidak dikenal → mirror 1920x1080@60 juga

hl.monitor({
    output   = "",
    mode     = "1920x1080@60",
    position = "auto",
    scale    = 1,
    mirror = "LVDS-1",
})
